// Har run me LIMIT "Discovered + Exact" candidates chuno, chaaron pool baari-baari, open_to_work wale pehle
const LIMIT = 50;          // har run me kitne profiles ($0.01 each). 2 run = 100 per day
const TABS = [['Read ServiceNow rows', 'ServiceNow'], ['Read AI_ML rows', 'AI_ML'], ['Read Salesforce rows', 'Salesforce'], ['Read Workday rows', 'Workday']];
const lists = TABS.map(([node, tab]) => $(node).all().map(i => i.json)
  .filter(r => r.linkedin_url && r.readiness === 'Discovered' && r.title_match === 'Exact')
  .sort((a, b) => (b.open_to_work === 'Yes') - (a.open_to_work === 'Yes') || String(a.first_seen).localeCompare(String(b.first_seen)))
  .map(r => ({ tab, row: r })));
const picks = [];
while (picks.length < LIMIT && lists.some(l => l.length))
  for (const l of lists) if (l.length && picks.length < LIMIT) picks.push(l.shift());
if (!picks.length) return [];
return [{ json: { picks, urls: picks.map(p => p.row.linkedin_url.replace('://in.linkedin.com', '://www.linkedin.com')) } }];

