const TAB_POOL = Object.fromEntries(Object.values(POOLS).map(p => [p.tab, p]));

// ===== Location: city -> [city, state, country]. India ke saath duniya bhar =====
const IN = (c, s) => [c, s, 'India'];
const GEO = {
  bengaluru: IN('Bengaluru','Karnataka'), bangalore: IN('Bengaluru','Karnataka'), mysuru: IN('Mysuru','Karnataka'), mysore: IN('Mysuru','Karnataka'),
