  'navi mumbai': IN('Navi Mumbai','Maharashtra'), thane: IN('Thane','Maharashtra'), nagpur: IN('Nagpur','Maharashtra'), pimpri: IN('Pune','Maharashtra'),
  chennai: IN('Chennai','Tamil Nadu'), coimbatore: IN('Coimbatore','Tamil Nadu'), noida: IN('Noida','Uttar Pradesh'), 'greater noida': IN('Greater Noida','Uttar Pradesh'),
