  dublin: ['Dublin','','Ireland'], amsterdam: ['Amsterdam','','Netherlands'], berlin: ['Berlin','','Germany'], munich: ['Munich','','Germany'], frankfurt: ['Frankfurt','','Germany'],
  paris: ['Paris','','France'], zurich: ['Zurich','','Switzerland'], sydney: ['Sydney','New South Wales','Australia'], melbourne: ['Melbourne','Victoria','Australia'],
